pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: Set MinSum to 1 ether, then initialize so no further changes
        c.SetMinSum(1 ether);
        c.Initialized();
        // Now fund the contract with 1 ether via fallback
        vm.deal(address(this), 1 ether);
        (bool ok,) = address(c).call{value: 1 ether}("");
        assertTrue(ok);
        // Warp past unlock time (unlockTime is 0 + 0 = 0, already passed)
        // Collect should succeed if MinSum == 1 ether (reference) or fail if MinSum == 0 (buggy)
        vm.prank(address(this));
        // use try/catch to capture revert as boolean
        bool collectOk;
        try c.Collect(1 ether) {
            collectOk = true;
        } catch {
            collectOk = false;
        }
        // Reference: MinSum = 1 ether, balance >= MinSum => Collect succeeds
        // Buggy: MinSum = 0, balance >= MinSum (1 ether >= 0) but balance >= 1 ether also true, so Collect succeeds? Wait: buggy SetMinSum does nothing, MinSum stays 0, condition acc.balance >= MinSum && acc.balance >= _am && ... => 1 ether >= 0 && 1 ether >= 1 ether && block.timestamp > unlockTime (unlockTime=0) => true, so Collect would succeed in both. Need a different scenario.
