        // Reset contract: deploy new one each test, can't reset state; but setUp deploys fresh. So redo scenario:
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a specific scenario: call SetMinSum with value 100
        vm.prank(address(0x1));
        c.SetMinSum(100);
        // Assert that MinSum is 100 in the reference version
        assertEq(c.MinSum(), 100);
    }
}

