pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract
        c.Initialized();
        // Step 2: Fund an account (say address(1)) with 1 ether
        address user = address(1);
        vm.deal(user, 1 ether);
        vm.prank(user);
        // Step 3: Call SetLogFile with a non-zero address (here a dummy address)
        // In the reference version, this sets Log to that address.
        // In the buggy version, Log remains address(0).
        c.SetLogFile(address(2));
        // Step 4: Now user calls Put with value 0.5 ether and lockTime 0.
        // In the reference, Put succeeds (since Log is set).
        // In the buggy version, Put will revert because Log.AddMessage calls on a zero address.
        vm.prank(user);
        bool ok;
        try c.Put{value: 0.5 ether}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference should succeed, buggy should fail.
        assertTrue(ok);
    }
}

