pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 so any balance >= 0 is sufficient
        c.SetMinSum(0);
        c.Initialized();

        // Fund test address with 1 ether
        address user = address(0x123);
        vm.deal(user, 1 ether);

        // User puts 1 ether with lockTime 100 seconds
        vm.prank(user);
        c.Put{value: 1 ether}(100);

        // Warp to after unlockTime
        // unlockTime = block.timestamp + 100, so warping 200 seconds ensures it's past
        vm.warp(block.timestamp + 200);

        // User collects 1 ether - should succeed
        vm.prank(user);
        c.Collect(1 ether);

        // Check user's balance after collection
        // In reference, balance should be 0
        // In modified (without unlockTime update), balance may still be 0 if collect succeeded
        // But the real divergence: in reference, unlockTime was updated to max of old and new timestamp+lockTime
        // which doesn't matter here. The key is that Collect succeeded in both.
        // Actually the divergence is that the missing line means unlockTime is never updated.
        // Let's verify by checking that after Collect, the user's unlockTime is still the old value
        (uint unlockTime,) = c.Acc(user);
        // Reference: unlockTime unchanged by Collect, but Put updated it to block.timestamp+100 at the time of Put
        // The modified version never updates unlockTime in Put, so it defaults to 0
        // So reference unlockTime > 0, modified unlockTime == 0
        assertTrue(unlockTime > 0);
    }
}

