pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 and initialize
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Give user address this test some ether
        address user = address(this);
        vm.deal(user, 10 ether);

        // Now deposit 1 ether with a lock time of 100 seconds
        vm.warp(1000);
        c.Put{value: 1 ether}(100);

        // Warp to block.timestamp = 1050 (should still be locked if unlockTime = 1000+100=1100)
        vm.warp(1050);

        // Try to collect 1 ether (should revert because not unlocked yet)
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }

        // In reference, unlockTime = 1100 > 1050, so Collect reverts -> ok = false
        // In bug, unlockTime remained 0, so Collect succeeds -> ok = true
        assertTrue(!ok);
    }
}

