pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 so that balance >= MinSum is true
        c.SetMinSum(0);
        c.Initialized();

        // Give user address(this) some ether and call Put with _lockTime = 100 and msg.value = 1
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.Put{value: 1}(100);

        // Warp to a time after the unlockTime (block.timestamp starts at 1, so warp to block.timestamp=200)
        vm.warp(200);

        // Now collect the 1 wei
        vm.prank(address(this));
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, Collect should succeed and reduce balance to 0.
        // In the buggy version, unlockTime is never updated, so block.timestamp > unlockTime is false and Collect reverts -> ok = false.
        assertTrue(ok);
    }
}

