    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract (SetMinSum, SetLogFile, Initialized)
        vm.prank(address(this));
        c.SetMinSum(0);
        vm.prank(address(this));
        c.SetLogFile(address(0x123));
        vm.prank(address(this));
        c.Initialized();

        // Set up a user
        address user = address(0xdead);
        vm.deal(user, 1 ether);

        // User calls Put(100) with 1 ether
        vm.prank(user);
        c.Put{value: 1 ether}(100);

        // Attempt Collect immediately – should revert because block.timestamp <= unlockTime
        vm.prank(user);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", 0.5 ether));
        assertTrue(!ok);
    }
}

