pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize contract
        c.SetMinSum(0);
        c.Initialized();

        // Send 1 ether via Put with lockTime=100, timestamp starts at 1
        vm.warp(1);
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        c.Put{value: 1 ether}(100);

        // Expected unlockTime = 1 + 100 = 101; try Collect before that should revert
        // Warp to time 50 (before unlock) and try Collect(1 ether)
        vm.warp(50);
        vm.prank(address(0x1234));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 ether));
        // Reference: ok == false (Collect should revert because block.timestamp < unlockTime)
        // Buggy version: ok == true (unlockTime incorrectly set to 0, so collect succeeds)
        assertTrue(!ok);
    }
}

