pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize contract, set MinSum to 0 so Collect can proceed
        c.SetMinSum(0);
        c.Initialized();

        // First call to Put: lockTime = 100, unlockTime will be updated from 0 to 100 in reference
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(100);

        // Collect attempt should fail if unlockTime is 100 (as in reference) but succeed if unlockTime is 50 (buggy version)
        // So we try to Collect and check the revert boolean
        bool ok;
        try c.Collect(0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference, unlockTime=100, current time=0, so Collect reverts and ok is false
        // In buggy, unlockTime remains 50, so Collect succeeds and ok is true
        // We assert false because reference version makes ok false
        assertTrue(!ok);
    }
}

