pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract to enable normal operation
        vm.startPrank(address(0x1));
        c.Initialized();
        vm.stopPrank();

        // Send 1 wei via fallback (calls Put(0))
        vm.deal(address(0x2), 1 ether);
        vm.prank(address(0x2));
        (bool ok,) = address(c).call{value: 1}("");
        assertTrue(ok);

        // Now read the first element of LogFile's History array
        // In the reference version it exists, in the buggy version it reverts
        bool historyExists;
        try c.Log_History(0) returns (address, string memory, uint, uint) {
            historyExists = true;
        } catch {
            historyExists = false;
        }
        assertTrue(historyExists);
    }
}

